from render import build, card
from lib import R, chips
def ccard(i,label,text,refs,note=''):
    return card(f'part{i}',label,raw=f'\n          <p class="verse-scripture creed-text">{text}</p>',chips=chips([R(r) for r in refs],6),note=note).replace('creed-card--long','creed-card--creed')

def apostles():
    S=[("God the Father","I Believe in God the Father Almighty, Maker of heaven and earth:",["genesis 1:1","acts 17:24"]),
    ("Jesus Christ his only Son","And in Jesus Christ his only Son, our Lord;",["john 3:16","philippians 2:11","acts 2:36"]),
    ("Born, suffered, crucified","Who was conceived by the Holy Ghost, Born of the Virgin Mary, Suffered under Pontius Pilate, Was crucified, dead, and buried;",["luke 1:35","matthew 1:20","matthew 27:2","1-corinthians 15:3"]),
    ("“He descended into hell”","He descended into hell;",["acts 2:27","1-peter 3:19","ephesians 4:9"]),
    ("Risen, ascended, coming to judge","The third day he rose again from the dead; He ascended into heaven, And sitteth on the right hand of God the Father Almighty; From thence he shall come to judge the quick and the dead.",["1-corinthians 15:4","acts 1:9","hebrews 1:3","acts 10:42","2-timothy 4:1"]),
    ("The Spirit, the church, and the life to come","I believe in the Holy Ghost; The holy Catholick Church; The Communion of Saints; The Forgiveness of sins; The Resurrection of the body; And the Life everlasting. Amen.",["john 14:26","ephesians 2:19","1-john 1:3","ephesians 1:7","1-corinthians 15:52","john 3:16"]),]
    notes={3:'<strong>“He descended into hell.”</strong> “Hell” here translates a word for the realm of the dead, and churches have read the line in more than one way. The Heidelberg Catechism (Question 44), which renders it “He descended into Hades,” applies it to Christ’s “inexpressible anguish, pains, and terrors which he suffered in his soul on the cross and before” [[schaff3]]. Some churches, among them the United Methodist Church, leave the line out of the creed in worship [[b_apostles]].'}
    items=[ccard(i,l,t,r,notes.get(i-1,'')) for i,(l,t,r) in enumerate(S,1)]
    return build(dict(slug='apostles-creed',title="The Apostles’ Creed",desc="The Apostles’ Creed in the 1662 Book of Common Prayer text, with its history, Scripture links, and where Arminian and Reformed churches stand.",
     eyebrow='Ecumenical Creed',h1='The Apostles’ Creed',sub='The baptismal creed of the Western church, confessed by Arminian and Reformed churches alike.',
     meta=['Final form by about 600–700','Text: Book of Common Prayer, 1662'],pill='Public domain',
     background=['Despite its name, the creed was not written by the apostles. It grew out of the questions put to candidates at baptism, such as those recorded in the <em>Apostolic Tradition</em> attributed to Hippolytus (about 200), and closely resembles the baptismal creed used at Rome in the third and fourth centuries [[b_apostles]].',
      'Its present wording reached final form in southwestern France in the late sixth or early seventh century, and by the time of Pope Innocent III (1198–1216) it was acknowledged as the official statement of faith of the whole Western church. It has never been officially recognized by the Eastern Orthodox churches [[b_apostles]].'],
     version='From Morning Prayer in the <em>Book of Common Prayer</em> (1662), the traditional English form. Spelling follows the 1762 Baskerville printing, with the old long “s” modernized [[bcp]]. Scripture links open our verse-by-verse commentary.',
     items=items,
     both=dict(intro='The creed is shared ground. It confesses the Trinity and the life, death, and resurrection of Christ, and it says nothing about the questions of election and grace that divide the two traditions.',
       arminian=['When John Wesley prepared the <em>Sunday Service</em> for American Methodists in 1784, he kept the Apostles’ Creed there and in the baptismal service [[watson]], while dropping the Nicene Creed from the Lord’s Supper, apparently because Morning Prayer, with the Apostles’ Creed, would already have been said [[umc_creeds]]. The <em>United Methodist Hymnal</em> prints it today [[umc_creeds]].',
                 'The Remonstrant Confession of 1621 appeals to “the two last Articles of the Apostles Creed” in its chapter on the life to come [[tcp_remconf]].'],
       reformed=['The Heidelberg Catechism (1563) gives the creed as the summary of what a Christian must believe (Questions 22–23) and expounds it article by article through Question 58 [[schaff3]].',
                 'The Belgic Confession (Article 9) “willingly” receives it as one of “the three creeds” [[schaff3]], and the Church of England’s Article 8 says that the three creeds “ought thoroughly to be received and believed” [[schaff3]].']),
    ))

def athanasian():
    T1="WHOSOEVER will be saved: before all things it is necessary that he hold the Catholick Faith. Which Faith except every one do keep whole and undefiled: without doubt he shall perish everlastingly."
    T2="And the Catholick Faith is this: That we worship one God in Trinity, and Trinity in Unity; Neither confounding the Persons: nor dividing the Substance. For there is one Person of the Father, another of the Son: and another of the Holy Ghost. But the Godhead of the Father, of the Son, and of the Holy Ghost, is all one: the Glory equal, the Majesty co-eternal."
    T3="Such as the Father is, such is the Son: and such is the Holy Ghost. The Father uncreate, the Son uncreate: and the Holy Ghost uncreate. The Father incomprehensible, the Son incomprehensible: and the Holy Ghost incomprehensible. The Father eternal, the Son eternal: and the Holy Ghost eternal. And yet there are not three eternals: but one eternal. As also there are not three incomprehensibles, nor three uncreated: but one uncreated, and one incomprehensible. So likewise the Father is Almighty, the Son Almighty: and the Holy Ghost Almighty. And yet there are not three Almighties: but one Almighty. So the Father is God, the Son is God: and the Holy Ghost is God. And yet there are not three Gods: but one God. So likewise the Father is Lord, the Son Lord: and the Holy Ghost Lord. And yet not three Lords: but one Lord. For like as we are compelled by the Christian verity: to acknowledge every Person by himself to be God and Lord; So are we forbidden by the Catholick Religion: to say, There be three Gods, or three Lords."
    T4="The Father is made of none: neither created, nor begotten. The Son is of the Father alone: not made, nor created, but begotten. The Holy Ghost is of the Father and of the Son: neither made, nor created, nor begotten, but proceeding. So there is one Father, not three Fathers; one Son, not three Sons: one Holy Ghost, not three Holy Ghosts. And in this Trinity none is afore, or after other: none is greater, or less than another; But the whole three Persons are co-eternal together: and co-equal. So that in all things, as is aforesaid: the Unity in Trinity, and the Trinity in Unity is to be worshipped. He therefore that will be saved: must thus think of the Trinity."
    T5="Furthermore, it is necessary to everlasting salvation: that he also believe rightly the Incarnation of our Lord Jesus Christ. For the right Faith is, that we believe and confess: that our Lord Jesus Christ, the Son of God, is God and Man; God, of the Substance of the Father, begotten before the worlds: and Man, of the Substance of his Mother, born in the world; Perfect God, and perfect Man: of a reasonable soul and human flesh subsisting; Equal to the Father, as touching his Godhead: and inferior to the Father, as touching his Manhood."
    T6="Who although he be God and Man: yet he is not two, but one Christ; One; not by conversion of the Godhead into flesh: but by taking of the Manhood into God; One altogether; not by confusion of Substance: but by unity of Person. For as the reasonable soul and flesh is one man: so God and Man is one Christ;"
    T7="Who suffered for our salvation: descended into hell, rose again the third day from the dead. He ascended into heaven, he sitteth on the right hand of the Father, God Almighty: from whence he shall come to judge the quick and the dead. At whose coming all men shall rise again with their bodies: and shall give account for their own works. And they that have done good shall go into life everlasting: and they that have done evil, into everlasting fire. This is the Catholick Faith: which except a man believe faithfully, he cannot be saved."
    S=[("The catholic faith",T1,[]),("One God in Trinity",T2,["matthew 28:19","2-corinthians 13:14"]),("Equal in glory",T3,["john 1:1","john 10:30","acts 5:3"]),
       ("Begotten and proceeding",T4,["john 1:14","john 15:26"]),("The Incarnation",T5,["john 1:14","philippians 2:6","galatians 4:4","john 14:28"]),
       ("One Christ",T6,["colossians 2:9","1-timothy 2:5","hebrews 2:14"]),("Judgment and the life to come",T7,["acts 1:9","john 5:28","matthew 25:46","2-corinthians 5:10"])]
    notes={0:'<strong>The warning clauses.</strong> The opening and closing sentences, which say that whoever does not hold this faith will perish, are often called the “damnatory clauses.” They have long been controversial, and they are a main reason the creed’s use in worship has been restricted, especially among Anglicans [[b_athanasian]].',
           3:'<strong>“And of the Son.”</strong> Like the Western form of the Nicene Creed, this creed says the Spirit proceeds from the Father and the Son. It was unknown in the East until the twelfth century [[b_athanasian]].'}
    items=[ccard(i,l,t,r,notes.get(i-1,'')) for i,(l,t,r) in enumerate(S,1)]
    return build(dict(slug='athanasian-creed',title='The Athanasian Creed',desc='The Athanasian Creed (Quicunque vult) in the 1662 Book of Common Prayer text, with its history, Scripture links, and where Arminian and Reformed churches stand.',
     eyebrow='Ecumenical Creed',h1='The Athanasian Creed',sub='<em>Quicunque vult</em>: a Latin confession of the Trinity and the Incarnation, received by the Reformation churches as one of “the three creeds.”',
     meta=['Probably 5th century, southern France','Text: Book of Common Prayer, 1662'],pill='Public domain',
     background=['The creed of about forty verses that opens <em>Quicunque vult</em> (“Whosoever will”) was not written by Athanasius of Alexandria (d. 373), whose name it later carried. Since the seventeenth century scholars have generally placed it in southern France in the fifth century. A lost work of Vincent of Lérins, discovered in 1940, contains much of its language, and Vincent or an admirer of his has been suggested as its author. The earliest known copy is found with the sermons of Caesarius of Arles (d. 542) [[b_athanasian]].',
      'The creed teaches the Trinity and the two natures of Christ in short balanced statements. It was unknown in the East until the twelfth century [[b_athanasian]]. The 1662 Prayer Book appoints it, in place of the Apostles’ Creed, at Morning Prayer on Christmas, Easter, Trinity Sunday and other feasts [[bcp]].'],
     version='From the <em>Book of Common Prayer</em> (1662), where it is printed as “the Creed of St. Athanasius.” Spelling follows the 1762 Baskerville printing, with the long “s” and its ligatures modernized [[bcp]]. The Prayer Book closes the creed with the “Glory be to the Father”; that doxology is omitted here. Section headings are ours.',
     items=items,
     both=dict(intro='Both traditions inherited the creed from the Reformation as a sound statement of the Trinity and the person of Christ. Their hesitations about it, where they have any, concern its warning clauses and its place in worship, not its doctrine.',
       arminian=['The Methodist theologian Geoffrey Wainwright writes that John Wesley “particularly disliked the damnatory clauses of the so-called Athanasian Creed” [[watson]]. When he abridged the Thirty-nine Articles for American Methodists in 1784, he left out Article 8, which names the three creeds [[schaff3]].',
                 'Article 1 of the Methodist Articles of Religion keeps the creed’s doctrine in its own words: “in unity of this Godhead there are three persons, of one substance, power, and eternity” [[schaff3]].'],
       reformed=['The Belgic Confession (Article 9) says, “we do willingly receive the three creeds, namely, that of the Apostles, of Nice, and of Athanasius” [[schaff3]].',
                 'Article 8 of the Church of England’s Articles says the three creeds “ought thoroughly to be received and believed: for they may be proved by most certain warrants of Holy Scripture” [[schaff3]].']),
    ))

def chalcedon():
    T="We, then, following the holy Fathers, all with one consent, teach men to confess one and the same Son, our Lord Jesus Christ, the same perfect in Godhead and also perfect in manhood; truly God and truly man, of a reasonable [rational] soul and body; consubstantial [coessential] with the Father according to the Godhead, and consubstantial with us according to the Manhood; in all things like unto us, without sin; begotten before all ages of the Father according to the Godhead, and in these latter days, for us and for our salvation, born of the Virgin Mary, the Mother of God, according to the Manhood; one and the same Christ, Son, Lord, Only-begotten, to be acknowledged in two natures, inconfusedly, unchangeably, indivisibly, inseparably; the distinction of natures being by no means taken away by the union, but rather the property of each nature being preserved, and concurring in one Person and one Subsistence, not parted or divided into two persons, but one and the same Son, and only begotten, God the Word, the Lord Jesus Christ, as the prophets from the beginning [have declared] concerning him, and the Lord Jesus Christ himself has taught us, and the Creed of the holy Fathers has handed down to us."
    parts=T.split('; ')
    p1='; '.join(parts[:4])+';'
    rest='; '.join(parts[4:])
    a,b=rest.split('; one and the same Christ')
    S=[("One Son, perfect God and perfect man",p1,["john 1:1","john 1:14","colossians 2:9"]),
       ("Like us, without sin",a+';',["hebrews 4:15","galatians 4:4","luke 1:35"]),
       ("Two natures, one person","One and the same Christ"+b,["philippians 2:6","1-timothy 2:5","romans 1:3"])]
    notes={2:'<strong>“In two natures.”</strong> Schaff notes that this phrase was directed against Eutyches; the council’s delegates insisted on “in two natures” rather than “from two natures,” which could be read to mean that after the union Christ had only one nature [[schaff2]].',
           1:'<strong>“Mother of God.”</strong> Schaff notes that the Greek title <em>Theotokos</em> (“God-bearer”) was directed against Nestorius and was meant “to assert the true divinity of Christ and the realness of the Incarnation,” and that it is immediately qualified by “according to the Manhood” [[schaff2]].'}
    items=[ccard(i,l,t,r,notes.get(i-1,'')) for i,(l,t,r) in enumerate(S,1)]
    return build(dict(slug='chalcedonian-definition',title='The Chalcedonian Definition (451)',desc='The Definition of the Council of Chalcedon (451) on the two natures of Christ, in Philip Schaff’s public-domain translation, with background and Scripture links.',
     eyebrow='Ecumenical Definition',h1='The Chalcedonian Definition',sub='The Council of Chalcedon’s confession of Christ, one person in two natures.',
     meta=['Council of Chalcedon, 451','Text: Philip Schaff’s translation, 1877'],pill='Public domain',
     background=['The Council of Chalcedon was called by the Emperor Marcian in 451 and was attended by about 520 bishops. It approved the Nicene creeds, letters of Cyril of Alexandria, and the <em>Tome</em> of Pope Leo I, and it confessed Christ as one person in two natures, against the view that after the union he had only one nature [[b_chalcedon]].',
      'In the council’s acts the Definition follows a confirmation of the Nicene Creed in both its forms, of 325 and 381. Schaff explains that the council justified a new statement by the disputes over Christ’s person that had arisen since, associated with Apollinaris, Nestorius and Eutyches [[schaff2]].'],
     version='The definition proper, in the English translation printed by Philip Schaff in <em>The Creeds of Christendom</em>, vol. 2 (1877) [[schaff2]]. Words in square brackets are Schaff’s. The council’s longer preamble and its canons are not included. Section headings are ours.',
     items=items,
     both=dict(intro='There is no Arminian–Reformed disagreement over Chalcedon. Both traditions inherited its teaching through the Reformation confessions, and both state it in their own words.',
       arminian=['Article 2 of the Methodist Articles of Religion says that “two whole and perfect natures—that is to say, the Godhead and manhood—were joined together in one person, never to be divided, whereof is one Christ, very God and very man” [[schaff3]].'],
       reformed=['The Belgic Confession (Article 19) teaches that in Christ there are “not two Sons of God, nor two persons, but two natures united in one single person; yet each nature retains its own distinct properties” [[schaff3]].']),
    ))
if __name__=='__main__':
    for f in (apostles,athanasian,chalcedon): print(f.__name__, f())
